  "Send": "发送",
  "Send Message": "发送消息",
  "Send a friend a free week of Claude Code. If they love it and subscribe, you'll get {rewardAmount} in usage credits to keep building. <termsLink>Terms apply</termsLink>": "送给好友一周免费的 Claude Code。如果他们喜欢并订阅，您将获得 {rewardAmount} 的用量额度以继续构建。<termsLink>适用条款</termsLink>",
  "Send a friend a free week of Claude Code. If they love it and subscribe, you'll get {rewardAmount} of extra usage to keep building. <termsLink>Terms apply</termsLink>": "赠送好友一周免费的 Claude Code。如果他们在使用后订阅，您将获得价值 {rewardAmount} 的额外用量抵扣，以继续开展您的项目。<termsLink>条款适用</termsLink>",
  "Send a friend a free week of Claude Code. If they love it and subscribe, you’ll get {rewardAmount} in usage credits to keep building. <termsLink>Terms apply</termsLink>": "送给朋友一周免费的 Claude Code。如果他们喜欢并订阅，您将获得 {rewardAmount} 的用量积分以继续构建。<termsLink>条款适用</termsLink>",
  "Send a friend a free week of Claude Cowork. If they love it and subscribe, you'll get {rewardAmount} in usage credits to keep building. <termsLink>Terms apply</termsLink>": "送给朋友一周免费的 Claude Cowork。如果他们喜欢并订阅，你将获得 {rewardAmount} 的用量额度以继续构建。<termsLink>条款适用</termsLink>",
  "Send a friend a free week of Claude Cowork. If they love it and subscribe, you'll get {rewardAmount} of extra usage to keep building. <termsLink>Terms apply</termsLink>": "送朋友一周免费 Claude Cowork。如果他们喜欢并订阅，您将获得价值 {rewardAmount} 的额外用量。<a>须符合条款</a>",
  "Send a friend a free week of Claude Cowork. If they love it and subscribe, you’ll get {rewardAmount} in usage credits to keep building. <termsLink>Terms apply</termsLink>": "送给朋友一周免费的 Claude Cowork。如果他们喜欢并订阅，您将获得 {rewardAmount} 的用量积分以继续构建。<termsLink>条款适用</termsLink>",
  "Send a friend a free week of Claude Design. If they love it and subscribe, you’ll get {rewardAmount} in usage credits to keep building. <termsLink>Terms apply</termsLink>": "送给朋友一周免费的 Claude Design。如果他们喜欢并订阅，您将获得 {rewardAmount} 的用量积分以继续构建。<termsLink>适用条款</termsLink>",
  "Send a friend a free week of Cowork. If they love it and subscribe, you'll get {rewardAmount} in usage credits. <termsLink>Terms apply</termsLink>": "送给好友一周免费的 Cowork。如果他们喜欢并订阅，您将获得 {rewardAmount} 的用量额度。<termsLink>适用条款</termsLink>",
  "Send a friend a free week of Cowork. If they love it and subscribe, you'll get {rewardAmount} of extra usage. <termsLink>Terms apply</termsLink>": "赠送好友一周免费的 Cowork。如果他们喜欢并订阅，您将获得 {rewardAmount} 的额外用量。<termsLink>条款适用</termsLink>",
  "Send a friend a free week of Cowork. If they love it and subscribe, you’ll get {rewardAmount} in usage credits. <termsLink>Terms apply</termsLink>": "送给朋友一周免费的 Cowork。如果他们喜欢并订阅了，您将获得 {rewardAmount} 的用量积分。<termsLink>适用条款</termsLink>",
  "Send a guest pass to a friend. They'll get a free week to see what they can build with Claude. <termsLink>Terms apply</termsLink>": "送一张访客卡给朋友。他们将获得一周的免费体验时长，看看能用 Claude 构建什么。<termsLink>条款适用</termsLink>",
  "Send a guest pass to a friend. They'll get a free week to try Cowork. <termsLink>Terms apply</termsLink>": "送给朋友一张访客卡。他们将获得一周的免费 Cowork 试用期。<termsLink>条款适用</termsLink>",
  "Send a guest pass to a friend. They’ll get a free week to see what they can build with Claude. <termsLink>Terms apply</termsLink>": "向朋友发送一张访客通行证。他们将获得一周免费时间，体验他们能用 Claude 构建什么。<termsLink>适用条款</termsLink>",
  "Send a guest pass to a friend. They’ll get a free week to try Claude Design. <termsLink>Terms apply</termsLink>": "向朋友发送一张访客通行证。他们将获得一周免费试用 Claude Design 的机会。<termsLink>适用条款</termsLink>",
  "Send a guest pass to a friend. They’ll get a free week to try Cowork. <termsLink>Terms apply</termsLink>": "向朋友发送一张访客通行证。他们将获得一周免费试用 Cowork。<termsLink>适用条款</termsLink>",
