  "Sent": "已发送",
  "Sent alongside the IAP token on every proxied request — for backends behind IAP with their own API key. Cannot target a header the IAP handler already uses: the IAP token’s header, or Authorization when App audience is set. Values are write-only and never shown after saving.": "在每个代理请求中与 IAP 令牌一同发送——适用于位于 IAP 之后、拥有自己 API 密钥的后端。不能指向 IAP 处理器已使用的标头：IAP 令牌的标头，或设置了 App audience 时的 Authorization。值为只写，保存后不会显示。",
  "Sent as an Authorization: Basic header on every proxied request to allowed hosts. Values are write-only and never shown after saving.": "会在每个代理到允许主机的请求中作为 Authorization: Basic 请求头发送。值为只写，保存后不会再次显示。",
  "Sent as an Authorization: Basic header on every proxied request to matching hosts. Values are write-only and never shown after saving.": "作为 Authorization: Basic 标头发送到匹配主机的每个代理请求。值是只写的，保存后不再显示。",
  "Sent as the X-Amzn-Bedrock-Service-Tier header. Leave unset for on-demand.": "作为 X-Amzn-Bedrock-Service-Tier 标头发送。按需使用时请留空。",
  "Sent by {serverName}": "由 {serverName} 发送",
  "Sent edited plan": "发送了已编辑的计划",
  "Sent on every MCP request alongside the OAuth bearer token. Installers provide the values when they connect.": "会随 OAuth bearer token 一起在每个 MCP 请求中发送。安装者在连接时提供这些值。",
  "Sent on every MCP request alongside the OAuth bearer token. Values are stored securely and never shown again.": "在每个 MCP 请求中随 OAuth bearer 令牌一同发送。值会被安全存储且不再显示。",
  "Sent on every MCP request as this connector’s credentials, such as an API key. Values are stored securely and never shown again.": "作为此连接器的凭据（例如 API 密钥）随每个 MCP 请求发送。值会被安全存储，且不再显示。",
