  "Sessions couldn’t be loaded. Refresh to try again.": "无法加载会话。请刷新以重试。",
  "Sessions created": "已创建的会话",
  "Sessions fire with your Claude Code settings, CLAUDE.md, and skills.": "会话会使用你的 Claude Code 设置、CLAUDE.md 和技能触发。",
  "Sessions in a project share memory and instructions, so context carries forward and Claude can work more autonomously.": "项目中的会话共享记忆和指令，因此上下文可以延续，Claude 也能更自主地工作。",
  "Sessions in their own window stay responsive when the main window is hidden": "主窗口隐藏时，独立窗口中的会话仍保持响应",
  "Sessions in this project aren’t deleted.": "此项目中的会话不会被删除。",
  "Sessions in this project will be archived and become read-only.": "此项目中的会话将被归档并变为只读。",
  "Sessions per day": "每天的会话数",
  "Sessions queued": "会话已排队",
  "Sessions remember your scroll position when you come back to them": "当你重新回到会话时，它们会记住你的滚动位置",
