  "Sessions will no longer be able to authenticate against the configured hosts. This action cannot be undone.": "会话将不再能够针对配置的主机进行身份验证。此操作无法撤销。",
  "Sessions with an open draft PR no longer show or sort as closed": "带有开放草稿 PR 的会话不再显示或排序为已关闭",
  "Sessions with uncommitted changes are no longer auto-archived": "有未提交更改的会话不再自动归档",
