  "Set user and org spend limits": "设置用户和组织的支出限额",
  "Set via ?gb_gate_* / ?gb_feature_* query parameters. These persist in this browser until removed, and win over the overrides above. Add ?gb_clear=1 to any URL to drop them all.": "通过 ?gb_gate_* / ?gb_feature_* 查询参数设置。这些参数会在此浏览器中持续保留直至被移除，并优先于上方的覆盖项。在任意 URL 中添加 ?gb_clear=1 即可全部清除。",
  "Set your usage to a specific percentage.": "将您的用量设为特定百分比。",
  "Sets which repositories Claude can scan.": "设置 Claude 可以扫描哪些存储库。",
  "Setting": "设置",
  "Setting a folder keeps this project on this computer, so it won’t sync or share.": "设置文件夹会将此项目保留在此电脑上，因此它不会同步或共享。",
  "Setting a limit to $0 effectively disables additional spend": "将限制设置为 $0 可有效禁用额外支出",
  "Setting the stage for discovery...": "正在为发现/探索搭建舞台...",
