  "Show me 2 concepts for a journaling app": "给我看 2 个日记应用的概念",
  "Show me a complete analysis workflow on a realistic dataset: pick a domain I name, generate the data, then do the exploration, a model, and a findings summary — explaining every choice as you go.": "在一个逼真的数据集上给我展示一个完整的分析工作流：选择一个我指定的领域，生成数据，然后进行探索、建模和发现总结——边做边解释每个选择。",
  "Show me a writing technique": "给我展示一个写作技巧",
  "Show me any tricks that can help me manage email": "展示一些可以帮我管理邮件的小技巧",
  "Show me how my seasonal patterns affect my scheduling and energy": "向我展示我的季节性模式如何影响我的日程安排和精力",
  "Show me how parallel tasks work with a concrete example: a status deck to draft, an inbox to catch up on, and a topic to research. Lay out how you’d split those into separate tasks running side by side, each in its own window, and what I’d get back from each. Then ask what’s actually on my plate and start the real ones in parallel.": "用一个具体例子向我展示并行任务是如何工作的：一份要起草的状态汇报、一个要跟进的收件箱、一个要研究的主题。说明你会如何把它们拆分成多个并行运行的任务，每个任务在各自的窗口中，以及我会从每个任务得到什么。然后问我实际在忙什么，并真正并行地开始执行。",
  "Show me insights about my meeting attendance patterns": "向我展示关于我会议出席模式的见解",
  "Show me three brand styles": "给我看三种品牌风格",
  "Show me three visual directions": "给我三个视觉方向",
  "Show me what my inbox says about my week — who I actually spend it with, which threads are waiting on me, and the three emails worth answering first. If my Gmail isn’t connected, walk me through connecting it — or ask me three quick questions about my week and do the same analysis from my answers.": "告诉我我的收件箱如何反映我的一周——我实际上和谁在一起、哪些邮件线程在等我，以及最值得先回复的三封邮件。如果我的 Gmail 还没连接，请引导我完成连接——或者问我三个关于这一周的快速问题，并从我的回答中做同样的分析。",
