  "Some hostname patterns aren't valid and will be skipped. Fix or remove them in <link>Settings</link>.": "部分主机名模式无效且将被跳过。请在<link>设置</link>中修正或移除它们。",
  "Some hostname patterns aren’t valid and will be skipped. Fix or remove them in <link>Settings</link>.": "部分主机名模式无效，将被跳过。请在<link>设置</link>中修复或移除它们。",
  "Some images were too large to attach. Maximum size is 30 MB.": "部分图片过大无法附加。最大尺寸为 30 MB。",
