  "Some of your usage credits are currently reserved by running scans.": "您的部分用量额度目前被运行中的扫描预留。",
  "Some or all of this plugin’s monitors can’t be displayed from the stored version. Re-sync the plugin from its marketplace to review them.": "无法从已存储的版本显示此插件的部分或全部监视器。请从其市场重新同步插件以查看它们。",
  "Some permissions granted to this {principalType, select, account {member} other {group}} aren’t shown because their settings are hidden or unavailable.": "由于设置被隐藏或不可用，此{principalType, select, account {成员} other {群组}}被授予的部分权限未显示。",
