  "Some settings in the file couldn’t be fully read: {keys}. Check them in the form before applying.": "文件中的某些设置无法被完全读取：{keys}。应用前请在表单中检查它们。",
  "Some settings in your administrator's configuration are deprecated or could cause issues. See Details, or share the report with your IT team.": "您管理员配置中的某些设置已弃用或可能导致问题。请查看详情，或与您的 IT 团队共享报告。",
  "Some settings in your configuration are deprecated or could cause issues. See Details, then open Setup to update them.": "你配置中的某些设置已弃用或可能导致问题。请查看详情，然后打开设置以更新它们。",
  "Some shared plugins couldn’t load.": "部分共享插件无法加载。",
  "Some shared skills couldn’t load.": "部分分享的技能无法加载。",
