  "Something went wrong managing this skill.": "管理此技能时出错。",
  "Something went wrong on our end — try again in a moment. If it persists, check status.claude.com.": "我们这边出了点问题——请稍后重试。如果问题持续，请查看 status.claude.com。",
  "Something went wrong on our end. Try launching again in a moment.": "我们这边出了些问题。请稍后重新启动。",
