  "Something went wrong when adding your usage credits. Contact support for help.": "添加用量积分时出现问题。请联系支持获取帮助。",
  "Something went wrong while connecting to GitHub. You can try again, or pick up where you left off.": "连接 GitHub 时出现问题。您可以重试，或从上次中断处继续。",
