  "Something went wrong while updating memory": "更新记忆时出错",
  "Something went wrong, so your cancellation and refund didn’t go through and your plan is still active. Contact support to finish your refund.": "出现了一些问题，导致您的取消和退款未能完成，您的套餐仍然处于有效状态。请联系支持以完成退款。",
