  "Support routing": "支持路由",
  "Supported billing currencies: {currencies}. Checkout will be blocked.": "支持的结算货币包括：{currencies}。结账流程将被中断。",
  "Supported out of the box — no further action needed.": "开箱即用 — 无需进一步操作。",
  "Supported out of the box — no further action needed. For high-traffic servers, prefer CIMD or Anthropic-held credentials — DCR registers a new client per user connection.": "开箱即用——无需进一步操作。对于高流量服务器，建议优先使用 CIMD 或 Anthropic 持有的凭据——DCR 会为每个用户连接注册一个新客户端。",
  "Supported. Anyone can connect without credentials.": "已支持。任何人都可以无需凭据进行连接。",
  "Suppress unprompted feature-announcement UI: the post-update “What’s new” nudge and new-feature tips. Users can still open release notes themselves.": "抑制未经触发的功能公告 UI：更新后的“新功能”提示和新功能小贴士。用户仍可自行打开发行说明。",
  "Surface": "表面/显示层",
