  "Switch to {planName}. Your plan changes at your next billing date — you keep full access to your current plan until then.": "切换到 {planName}。您的套餐将在下一个计费日变更——在此之前，您仍可完整使用当前套餐。",
  "Switch to {targetLabel}": "切换到 {targetLabel}",
