  "Switching to Max 5x means you’ll have less usage and may hit your limits faster.": "切换到 Max 5x 意味着您的用量会变少，并且可能更快达到限额。",
  "Switching to Pro means you’ll have less usage, lose early access to new features, and won’t get priority at busy times.": "切换到 Pro 意味着您的用量会减少，失去对新功能的抢先体验，并且在繁忙时段无法获得优先权。",
