  "Team size and spend are observed from your org’s usage. Productivity lift is observed from your PR attribution data when sample size is sufficient, otherwise it falls back to the Anthropic enterprise benchmark. You can override any calibration below.": "团队规模和支出是根据您组织的使用情况观察得出的。生产力提升则根据您的 PR 归因数据观察；当样本量足够时使用该数据，否则回退到 Anthropic 企业基准。您可以在下方覆盖任何校准值。",
