  "That email is already a member of this workspace.": "该邮箱已是此工作区成员。",
  "That file is over the 10MB limit. Choose a smaller file.": "该文件超过了 10MB 限制。请选择较小的文件。",
  "That file isn’t a PDF. Choose a PDF file.": "该文件不是 PDF。请选择一个 PDF 文件。",
  "That folder can’t be used. Choose another.": "无法使用该文件夹。请选择其他文件夹。",
  "That image is too large. Choose one under 2 MB.": "该图像太大。请选择小于 2 MB 的图像。",
  "That image is too large. Choose one under 256 KB.": "该图像太大。请选择小于 256 KB 的图像。",
  "That link couldn't be verified. Enter the code shown in the app to continue.": "无法验证该链接。请输入应用中显示的代码以继续。",
  "That link couldn’t be verified. Enter the code shown in the app to continue.": "无法验证该链接。请输入应用中显示的代码以继续。",
  "That looks like {kind, select, anthropic_api_key {an Anthropic API key} openai_style_key {an API key} stripe_key {a Stripe API key} github_token {a GitHub token} gitlab_token {a GitLab token} slack_token {a Slack token} aws_access_key {an AWS access key} google_api_key {a Google API key} google_oauth_secret {a Google OAuth client secret} bearer_header {an Authorization header} private_key {a private key} other {a secret}}, not a client ID. Did you mean to paste this into Client Secret below?": "这看起来像{kind, select, anthropic_api_key {一个 Anthropic API 密钥} openai_style_key {一个 API 密钥} stripe_key {一个 Stripe API 密钥} github_token {一个 GitHub 令牌} gitlab_token {一个 GitLab 令牌} slack_token {一个 Slack 令牌} aws_access_key {一个 AWS 访问密钥} google_api_key {一个 Google API 密钥} google_oauth_secret {一个 Google OAuth 客户端密钥} bearer_header {一个 Authorization 头} private_key {一个私钥} other {一个机密信息}}，而不是客户端 ID。您是想把它粘贴到下方的“客户端密钥”里吗？",
  "That name is already taken.": "该名称已被占用。",
  "That name is in use by another project in your organization.": "该名称已被你组织中的另一个项目使用。",
