  "Usage analytics help us prioritize improvements for third-party inference. Diagnostic-report uploads will also be blocked. No message content is included in either.": "用量分析帮助我们优先改进第三方推理。诊断报告上传也将被阻止。两者均不包含任何消息内容。",
