  "Usage credits are valid for {months, plural, one {# month} other {# months}}. <link>Learn more</link>": "用量积分有效期为 {months, plural, one {# 个月} other {# 个月}}。<link>了解更多</link>",
  "Usage credits available at API rates": "可按 API 费率使用的用量额度",
  "Usage credits draw down as you go. Good for occasional busy days.": "用量额度会随用随扣。适合偶尔繁忙的日子。",
  "Usage credits keep you going when you hit your plan limits. If you're past a limit now, your current chat will get cut off.": "当你达到套餐限额时，用量额度可让你继续使用。如果你现在已超出限额，当前聊天将被中断。",
  "Usage credits keep you going when you hit your plan limits. If you’re past a limit now, your current chat will get cut off.": "用量积分可在您达到套餐限额时继续使用。如果您现在已经超出某个限额，您当前的聊天将被中断。",
  "Usage credits keep your team going when they hit a usage limit. If anyone is past a limit now, their current chat will get cut off.": "当你的团队达到用量限制时，用量额度可让他们继续工作。如果现在有人已超出限制，他们当前的聊天将被中断。",
