  "What needs your attention today across calendar, email, and messages.": "今天在日历、邮件和消息中有哪些需要您关注的事项。",
  "What other recurring tasks could you run on a schedule for me?": "你还能为我按计划运行哪些其他周期性任务？",
  "What reviewers check (review criteria)": "审查者检查的内容（审查标准）",
  "What shall we think through?": "我们应该思考什么？",
