  "What should change? (optional)": "应该改变什么？（可选）",
  "What shouldn't I use this for?": "我不应该把这用于什么？",
  "What specifically about Claude's responses didn't meet your expectations?": "Claude 的回答中有哪些具体内容未达到您的预期？",
  "What specifically about Claude’s responses didn’t meet your expectations?": "具体来说，Claude 的回复有哪些方面没有达到您的期望？",
  "What teams of your size and shape typically spend across our customer base.": "在我们的客户群中，与你规模和形态相似的团队通常的消费水平。",
  "What the server may request at sign-in. If blank, Desktop’s default read set is used.": "服务器在登录时可以请求的权限。如果留空，将使用桌面版默认的读取集合。",
  "What this URL is overriding": "此 URL 覆盖的内容",
