  "What type of issue do you wish to report? (optional)": "您想报告哪类问题？（可选）",
  "What types of errors or bugs most frequently disrupted your work?": "哪些类型的错误或故障最常干扰您的工作？",
  "What was satisfying about this response?": "这个回答让你满意的地方在哪里？",
