  "Work out my main project from my recent Notion activity, then build a hub page for it: links to the ten most relevant pages, current status, open items, and key decisions — one page that makes the project findable.": "从我近期的 Notion 活动中推断出我的主要项目，然后为它构建一个中心页面：链接到十个最相关的页面、当前状态、待办事项和关键决策——用一个页面让这个项目变得易于查找。",
  "Work out who I meet with most, then summarize our last few conversations: what we discussed, what was promised in each direction, and what’s still open between us.": "算出我和谁见面最多，然后总结我们最近的几次对话：讨论了什么、各自做了什么承诺、我们之间还有什么未了事项。",
