  "You don’t have permission to view this page.": "您没有权限查看此页面。",
  "You don’t have permission to view your organization’s connectors. Ask an organization owner for access.": "您没有权限查看您组织的连接器。请向组织所有者申请访问权限。",
  "You don’t have permission to view your organization’s plugins. Ask an organization owner for access.": "您没有权限查看您组织的插件。请向组织所有者申请访问权限。",
  "You don’t have permission to view your organization’s skills. Ask an organization owner for access.": "您没有权限查看您组织的技能。请向组织所有者申请访问权限。",
  "You don’t own any Team organizations yet. Create one to get nonprofit pricing.": "您尚未拥有任何 Team 组织。创建一个以获取非营利组织定价。",
