  "You won’t be able to view it again.": "您将无法再次查看它。",
  "You won’t be asked again for this workspace. Read our <securityLink>security guide</securityLink> for details.": "您不会再被询问此工作区。请阅读我们的<securityLink>安全指南</securityLink>了解详情。",
  "You won’t be charged while paused": "暂停期间不会向您收费",
