  "You'll keep access until {date}, and you won't be charged. If you subscribe later, it'll be at the standard rate—your promotional rate won't carry over.": "您将在 {date} 之前保留访问权限，并且不会被收费。如果您之后订阅，将按标准价格计费——您的优惠价格不会延续。",
