  "Your chats, projects, and settings stay exactly as you left them": "您的聊天、项目和设置保持您离开时的原样",
  "Your checkout session expired. Click Try again to start a new one.": "您的结账会话已过期。请点击“重试”以开始新的会话。",
  "Your choice is saved to .claude/launch.json in this project.": "您的选择会保存到此项目的 .claude/launch.json 中。",
  "Your company already has a Team plan. Ask your admin for an invite.": "您的公司已有团队方案。请向管理员索要邀请。",
  "Your company already has an Enterprise plan. Contact your admin for access.": "您的公司已有企业方案。请联系您的管理员以获取访问权限。",
  "Your company already uses Claude Enterprise": "您的公司已经在使用 Claude Enterprise",
