  "Your custom connectors": "您的自定义连接器",
  "Your custom style": "您的自定义样式",
  "Your data": "你的数据",
  "Your data export is in progress. A download link will be emailed to {hasEmail, select, yes {{email}} other {your address}} when it’s ready.": "您的数据导出正在进行中。完成后，下载链接会通过邮件发送到{hasEmail, select, yes {{email}} other {您的地址}}。",
  "Your data retention policy will apply to migrated content, starting from the migration date": "您的数据保留策略将适用于迁移内容，从迁移日期开始生效",
  "Your data won't be used to train our models": "您的数据不会被用于模型训练",
  "Your data won’t be used to train our models": "您的数据不会用于训练我们的模型",
