  "Your provider setup needs a fix": "你的提供商设置需要修复",
  "Your purchase from {time} is still processing. This usually takes a few seconds. If it doesn’t complete, you can try again in {minutes, plural, one {# minute} other {# minutes}}.": "您在 {time} 的购买仍在处理中。这通常只需要几秒钟。如果未完成，您可以在 {minutes, plural, one {# 分钟} other {# 分钟}} 后重试。",
  "Your purchase from {time} is waiting on card verification from your bank. Finish the verification in your bank’s app or popup, or wait. Unfinished attempts expire in {minutes, plural, one {# minute} other {# minutes}}. Trying a different card won’t help until then.": "您在 {time} 的购买正在等待银行的银行卡验证。请在您银行的应用或弹窗中完成验证，或者等待。未完成的尝试会在 {minutes, plural, one {# 分钟} other {# 分钟}} 后失效。在此之前，换一张卡也无济于事。",
