  "Your seat type doesn't include usage credits.": "你的席位类型不包含用量额度。",
  "Your seat type doesn't include usage credits. Manage spend limit to keep going now.": "你的席位类型不包含用量额度。请管理消费限额以立即继续。",
  "Your seat type doesn’t include extra usage.": "您的席位类型不包含额外用量。",
  "Your seat type doesn’t include extra usage. Manage spend limit to keep going now.": "您的席位类型不包含额外用量。请管理支出限额以继续使用。",
