  "Your server was saved but not yet submitted for review. You can keep editing and submit from the detail page.": "您的服务器已保存，但尚未提交审核。您可以继续编辑，并从详情页面提交。",
  "Your session expires in {remaining}": "您的会话将在 {remaining} 后过期",
  "Your session has expired for Claude Code access. Sign in again to reconnect.": "您的 Claude Code 访问会话已过期。请重新登录以重新连接。",
  "Your session has expired for Cowork access. Sign in again to reconnect this device.": "您的 Cowork 访问会话已过期。请重新登录以重新连接此设备。",
  "Your session has expired. You can reconnect to re-authorize.": "您的会话已过期。您可以重新连接以重新授权。",
  "Your session has timed out. You can reconnect to continue.": "您的会话已超时。您可以重新连接以继续。",
  "Your session will pause and the runner will be freed for other work. Any uncommitted files on the runner will be lost. Send a message to resume — it may pick up a different runner.": "您的会话将暂停，运行器将被释放以进行其他工作。运行器上任何未提交的文件都将丢失。发送消息以恢复 — 它可能会选择不同的运行器。",
  "Your sign-in session has expired, so Dispatch is disconnected on this device. Sign in again to reconnect.": "您的登录会话已过期，因此 Dispatch 已在此设备上断开连接。请重新登录以重新连接。",
  "Your skills": "您的技能",
