  "Your team can start using Claude now. When you’re ready for more, the Administrator Guide covers SCIM, audit logs, and org-wide rollout.": "您的团队现在就可以开始使用 Claude。当您需要更多功能时，管理员指南涵盖了 SCIM、审计日志和全组织推广。",
  "Your team has reached its {limit} seat limit. Request an increase to add more members.": "您的团队已达到 {limit} 个席位的上限。请申请增加限额以添加更多成员。",
