  "Your team is using {used} of {limit} seats on your current plan. You won’t be able to add new members once you reach the limit.": "您的团队在当前套餐上使用了 {used} / {limit} 个席位。达到限额后，您将无法添加新成员。",
  "Your team is using {used} of {limit} seats. You won't be able to add new members once you reach the limit.": "您的团队已使用 {used} 个席位，共 {limit} 个。达到限额后，您将无法添加新成员。",
  "Your team is using {used} of {limit} seats. You won’t be able to add new members once you reach the limit.": "您的团队正在使用 {limit} 个席位中的 {used} 个。一旦达到限额，您将无法添加新成员。",
