  "Your team's trial ends in {daysRemaining, plural, one {# day} other {# days}}. Charges begin {chargeDate}.": "您的团队试用将在 {daysRemaining, plural, one {# 天} other {# 天}}后结束。计费从 {chargeDate} 开始。",
  "Your team’s initial pool of usage. {editLink}": "您团队的初始用量池。{editLink}",
  "Your team’s promo ends in {daysUntil, plural, one {# day} other {# days}}. Charges begin {chargeDate}.": "您团队的促销将在 {daysUntil, plural, one {# 天} other {# 天}}后结束。收费将于 {chargeDate} 开始。",
  "Your team’s trial ends in {daysRemaining, plural, one {# day} other {# days}}. Charges begin {chargeDate}.": "您团队的试用还剩 {daysRemaining, plural, one {# 天} other {# 天}}结束。费用从 {chargeDate} 开始计算。",
  "Your tenant may not be allowlisted yet — send the Client ID and Tenant ID above to your Anthropic representative (2-3 business days to activate).": "您的租户可能尚未加入允许列表——请将上方的 Client ID 和 Tenant ID 发送给您的 Anthropic 代表（需 2-3 个工作日激活）。",
  "Your terminal's Claude Code session stopped responding. Check your terminal for errors, then resend your message.": "你终端中的 Claude Code 会话已停止响应。请检查终端中的错误，然后重新发送你的消息。",
  "Your terminal’s Claude Code session stopped responding. Check your terminal for errors, then resend your message.": "您终端的 Claude Code 会话已停止响应。请检查终端中的错误，然后重新发送您的消息。",
