  "Your usage allocation has been disabled by your admin.": "你的使用配额已被管理员禁用。",
  "Your usage allocation hasn't been set up yet.": "您的用量分配尚未设置。",
  "Your usage allocation hasn’t been set up yet.": "您的用量配额尚未设置。",
  "Your usage credit refund is on the way. Auto-reload is now off. Re-enable it in billing settings.": "您的用量积分退款正在进行中。自动重载现已关闭。请在计费设置中重新启用。",
  "Your usage is too large to display while this feature is in beta.": "由于此功能处于测试阶段，您的用量数据太大，无法显示。",
  "Your usage is unlimited. Reach out to your admin directly if you need help.": "你的使用量不受限制。如需帮助，请直接联系管理员。",
  "Your usage limits": "您的使用限制",
  "Your version of the Claude app is out of date. Please upgrade to the latest version to continue using Claude.": "您的 Claude 应用版本已过时。请升级至最新版本以继续使用 Claude。",
  "Your voice session has expired. You can start a new one.": "您的语音会话已过期。您可以开始一个新的。",
  "Your weekly limit across all models": "您跨所有模型的每周限额",
  "Your {amount} usage credit refund is on the way. Auto-reload is now off. Re-enable it in billing settings.": "您的 {amount} 用量积分退款正在进行中。自动重载现已关闭。请在计费设置中重新启用。",
  "Your {balance} in extra usage is ready to use. You can set a spend limit, or turn on auto-reload so you never run out.": "您的 {balance} 额外用量已可使用。您可以设置支出限额，或开启自动重载，这样就不会用完。",
  "Your {balance} in usage credits is ready to use. You can set a usage credit limit, or turn on auto-reload so you never run out.": "您的 {balance} 用量积分已可使用。您可以设置用量积分限额，或开启自动充值，让您永不断档。",
  "Your {resourceType} upload failed. Please try again.": "您的 {resourceType} 上传失败。请重试。",
  "Yours": "您的",
  "Yours, on this browser.": "您的，在此浏览器上。",
  "You’ll also get Claude in:": "您还将在以下产品中获得 Claude：",
  "You’ll be billed as soon as your next renewal date happens, unless you cancel.": "除非您取消，否则在下一个续订日期到来时将向您收费。",
  "You’ll be redirected to sign in": "您将被重定向以登录",
  "You’ll be sent to GitHub to install the Claude app on an organization you own.": "您将被引导至 GitHub，在您拥有的组织上安装 Claude 应用。",
  "You’ll get a <b>{amount}</b> refund for the rest of this billing period, sent to your original payment method.": "您将获得本计费周期剩余时间的 <b>{amount}</b> 退款，款项会退回您原来的付款方式。",
  "You’ll get a notification for every join request and approve them individually.": "您会收到每个加入请求的通知，并需要逐一审批。",
  "You’ll get a refund for <b>{amount}</b> (plus tax) of your unused usage credits, sent to your original payment method.": "您将收到 <b>{amount}</b>（含税）的未使用用量积分退款，退回到您的原付款方式。",
  "You’ll get an invoice with transfer instructions. Your plan starts once payment clears (1 to 5 business days).": "您将收到一张带有转账说明的发票。付款到账（1 到 5 个工作日）后，您的套餐随即开始。",
  "You’ll have the option to pay in your local currency at checkout.": "您可以在结账时选择使用当地货币支付。",
  "You’ll keep Pro until your annual plan ends on {date}, then move to the Free plan.": "在 {date} 年度套餐到期之前，您将保留 Pro，之后会转到 Free 套餐。",
  "You’ll keep Pro until your annual plan ends, then move to the Free plan.": "在年度套餐到期前您将继续保持 Pro，之后会转为免费套餐。",
  "You’ll keep access until {date} and won’t be charged.": "您将保留访问权限直到 {date}，且不会被收费。",
  "You’ll keep access until {date}, and you won’t be charged.": "您将保留访问权限直到 {date}，且不会被收费。",
  "You’ll keep access until {date}, and you won’t be charged. If you subscribe later, it’ll be at the standard rate—your promotional rate won’t carry over.": "您可以保留访问权限直到 {date}，且不会被收费。如果之后才订阅，将按标准费率计费——您的优惠费率不会延续。",
  "You’ll keep full access to {planName} until your billing period ends on {date}. After that, you’ll move to the Free plan.": "在 {date} 当前计费周期结束前，您将继续拥有 {planName} 的完整访问权限。之后，您将切换到 Free 套餐。",
  "You’ll keep full access to {planName} until your billing period ends. After that, you’ll move to the Free plan.": "在计费周期结束之前，您将继续保留对 {planName} 的完整访问权限。之后，您将转到 Free 套餐。",
  "You’ll keep full access to {productName} until your billing period ends on {nextChargeDate}. After that, you’ll move to the free plan.": "在 {nextChargeDate} 当前计费周期结束前，您可继续完整访问 {productName}。之后，您将转为免费套餐。",
  "You’ll keep the same features and usage limits. Monthly billing starts on {date}, when your annual plan ends.": "您将保留相同的功能和用量限额。月度计费将从 {date}（即您的年度套餐到期时）开始。",
  "You’ll keep the same features and usage limits. Monthly billing starts when your annual plan ends.": "您将保留相同的功能和用量限制。月度计费将在您的年度套餐结束时开始。",
  "You’ll lose access to": "你将失去对以下内容的访问权限：",
  "You’ll need to be an owner of the GitHub account to connect.": "您需要是该 GitHub 账户的所有者才能连接。",
  "You’ll need:": "您需要：",
  "You’ll only need to do this once. Any existing Google Drive capabilities in Claude will still work.": "您只需执行一次此操作。Claude 中任何现有的 Google 云端硬盘功能仍将正常使用。",
  "You’ll only see tools your organization has given you access to.": "您只会看到组织授予您访问权限的工具。",
  "You’ll pay": "您将支付",
  "You’ll pay a fixed price per seat. Usage is billed as you go based on what your team uses.": "您将按席位支付固定价格。用量根据您团队的实际使用情况按需计费。",
  "You’ll receive": "您将收到",
  "You’ll receive a <b>{amount}</b> prorated refund to your original payment method.": "您将收到 <b>{amount}</b> 的按比例退款到您的原始付款方式。",
  "You’ll receive an invoice with transfer instructions each billing period.": "您每个计费周期都会收到一张带有转账说明的发票。",
  "You’ll receive notifications when your tasks need attention.": "当您的任务需要关注时，您将收到通知。",
  "You’re about to make changes to your organization’s data retention period.": "您即将更改组织的 数据保留期。",
  "You’re all caught up": "您已全部处理完毕",
