  "You’re already Max’d out!": "您已经达到 Max 方案最大额度了！",
  "You’re approaching your {limitName}. It resets at {resetTime} on {resetDay}. To keep working without interruption:": "您即将达到 {limitName}。它将在 {resetDay} 的 {resetTime} 重置。要保持不间断地工作：",
  "You’re approaching your {limitName}. To keep working without interruption:": "您即将达到您的 {limitName}。为避免中断您的工作：",
