  "You’re currently viewing from {orgName}. This session may belong to another organization.": "您当前从 {orgName} 查看。此会话可能属于另一个组织。",
  "You’re currently within the {organizationName} organization.": "您当前处于 {organizationName} 组织中。",
  "You’re currently within the {organizationName} organization. ": "您当前位于 {organizationName} 组织中。",
  "You’re editing the note above — tap Done when you’re finished.": "您正在编辑上方的备注——完成后请点按“完成”。",
  "You’re in secure browsing mode. Update Claude Desktop to restore full performance and compatibility.": "您处于安全浏览模式。请更新 Claude Desktop 以恢复完整性能和兼容性。",
  "You’re in the process of migrating accounts using your domain. <b>Affected users have been notified and must join by {deadline}.</b>": "您正在使用您的域名迁移账户。<b>受影响的用户已被通知，必须在 {deadline} 前加入。</b>",
  "You’re incognito": "您处于隐身状态",
  "You’re leaving Claude to visit an external link:": "您即将离开 Claude 以访问外部链接：",
