  "You’re not signed in to this GitHub Enterprise instance. Connect your account to continue.": "您尚未登录此 GitHub Enterprise 实例。请连接您的账户以继续。",
  "You’re now on the free plan. Your chats and projects are still here.": "您现在使用的是免费套餐。您的聊天和项目仍然在这里。",
  "You’re now past your plan’s included usage.": "您已超出套餐包含的用量。",
  "You’re now past your plan’s included usage. Your plan limit resets {day} at {time}.": "您已超出套餐包含的用量。您的套餐限额将在 {day} {time} 重置。",
  "You’re on a free trial until {date}. Seats beyond your free allowance are charged at a prorated rate for the remaining trial days.": "您在 {date} 之前可免费试用。超出免费名额的席位将按剩余试用天数按比例计费。",
  "You’re only billed for what you end up using. Adjust anytime.": "您只需为最终使用的部分付费。可随时调整。",
  "You’re out of extra usage. Buy more to keep going now, or wait until {day} at {time} when your plan usage resets.": "您的额外用量已用完。立即购买更多以继续使用，或等到 {day} {time} 您的套餐用量重置。",
  "You’re out of extra usage. Buy more to keep going now, or wait until {time} when your plan usage resets.": "您的额外用量已用完。立即购买更多以继续使用，或等到 {time} 套餐用量重置。",
  "You’re out of extra usage. Buy more to keep going now.": "您的额外用量已用完。立即购买更多以继续使用。",
