  "You’re out of usage credits. Buy more to keep going now, or wait until {day} at {time} when your plan usage resets.": "您的用量积分已用完。立即购买更多以继续使用，或等到 {day} {time} 套餐用量重置。",
  "You’re out of usage credits. Buy more to keep going now, or wait until {time} when your plan usage resets.": "您的用量积分已用完。立即购买更多以继续使用，或等到 {time} 套餐用量重置。",
