  "You’re out of usage credits. Get more usage to keep going now, or wait until {day} at {time} when your plan usage resets.": "您的用量积分已用完。立即获取更多用量以继续使用，或等到 {day} {time} 套餐用量重置。",
  "You’re out of usage credits. Get more usage to keep going now, or wait until {time} when your plan usage resets.": "您的用量积分已用完。立即获取更多用量以继续使用，或等到 {time} 您的套餐用量重置。",
  "You’re out of usage credits. Get more usage to keep going now.": "您的用量积分已用完。立即获取更多用量以继续使用。",
