  "You’re signed in to Claude with a different email than your course roster uses. Sign in with the account your institution knows you by, then launch again from Canvas.": "您登录 Claude 使用的电子邮件与课程名册上的不同。请使用您的机构所认识的账户登录，然后从 Canvas 重新启动。",
  "You’re subscribed to the Enterprise plan. Create your team and invite teammates to use Claude together.": "您已订阅 Enterprise 套餐。创建您的团队并邀请队友一起使用 Claude。",
  "You’re subscribed via Android app": "您是通过 Android 应用订阅的",
