  "You’re using Claude via the Claude API. Your conversations are sent to Anthropic and governed by Anthropic’s {apiTerms}.": "您正在通过 Claude API 使用 Claude。您的对话会发送给 Anthropic，并受 Anthropic 的 {apiTerms} 约束。",
  "You’re using {provider}": "您正在使用 {provider}",
  "You’ve added custom roles, but they don’t apply to any members yet. Map groups to roles and then set members’ role type to <b>Custom</b> on the Members page.": "您已添加了自定义角色，但它们尚未应用于任何成员。请将群组映射到角色，然后在成员页面上将成员的角色类型设置为 <b>自定义</b>。",
