  "You’ve reached <link>your {period, select, daily {daily } weekly {weekly } monthly {monthly } other {}}spend limit</link>.": "您已达到<link>您的{period, select, daily {每日 } weekly {每周 } monthly {每月 } other {}}支出限额</link>。",
