  "You’ve reached your limit for {resourceType} uploads. Please try again later.": "您已达到 {resourceType} 上传上限。请稍后再试。",
  "You’ve reached your monthly spend limit and you’re out of credits. Raise your limit, then add credits to keep working.": "您已达到月度支出限额，并且积分已用完。请提高限额，然后添加积分以继续工作。",
